<script setup>
import {ref} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import {request} from '../../utils/request'
const current=ref(null),loading=ref(false),saving=ref(false),error=ref('')
const form=ref({school:'江西师范大学',college:'人工智能学院',realName:'',studentNumber:''})
const labels={PENDING:'审核中',APPROVED:'已通过',REJECTED:'未通过'}
async function load(){loading.value=true;error.value='';try{current.value=await request({url:'/api/campus/verification'});if(current.value){form.value={school:current.value.school,college:current.value.college,...current.value.identity}}}catch(e){error.value=e.message||'加载失败'}finally{loading.value=false}}
async function submit(){if(Object.values(form.value).some(v=>!v?.trim())){error.value='请填写完整的校园身份信息';return}saving.value=true;error.value='';try{await request({url:'/api/campus/verification',method:'POST',data:form.value});uni.showToast({title:'已提交审核',icon:'success'});await load()}catch(e){error.value=e.message||'提交失败'}finally{saving.value=false}}
onShow(load)
</script>
<template><view class="campus-page"><view class="campus-card"><text class="eyebrow">校园身份</text><text class="title">让校园连接更可信</text><text class="intro">提交信息后由管理员核实。身份审核不会改变账号权限，姓名和学号仅用于审核。</text><text v-if="loading" class="intro">正在读取申请…</text><view v-if="current" class="status"><text>{{labels[current.status]}}</text><text v-if="current.review_reason">{{current.review_reason}}</text></view><template v-if="!loading&&(!current||current.status==='REJECTED')"><text class="label">学校</text><input v-model="form.school" maxlength="100" placeholder="学校全称"/><text class="label">学院</text><input v-model="form.college" maxlength="100" placeholder="所在学院"/><text class="label">姓名</text><input v-model="form.realName" maxlength="40" placeholder="与校园登记一致的姓名"/><text class="label">学号</text><input v-model="form.studentNumber" maxlength="40" placeholder="请输入学号"/><button class="submit" :loading="saving" :disabled="saving" @click="submit">{{current?'重新提交':'提交审核'}}</button></template><text v-if="error" class="error">{{error}}</text><button v-if="error" size="mini" @click="load">重新加载</button></view><text class="disclaimer">本系统不能替代专业心理咨询</text></view></template>
<style scoped>.campus-page{padding:32rpx;background:var(--zy-bg,#f6f8f6);min-height:100vh}.campus-card{padding:36rpx;background:var(--zy-card,#fff);border-radius:32rpx;display:flex;flex-direction:column;gap:20rpx}.eyebrow{font-size:24rpx;color:#2f7566}.title{font-size:42rpx;font-weight:700;color:#203f35}.intro,.disclaimer{font-size:26rpx;line-height:1.8;color:#697a72}.label{margin-top:12rpx;font-size:26rpx}input{padding:22rpx;background:#f2f6f3;border-radius:16rpx;font-size:28rpx}.submit{margin-top:24rpx;width:100%;background:#2f7566;color:#fff}.status{display:flex;flex-direction:column;gap:12rpx;padding:24rpx;background:#edf5ef;border-radius:20rpx}.error{color:#a73d3d;font-size:26rpx}.disclaimer{display:block;text-align:center;margin-top:36rpx}</style>
